// Reading sentence: built only from spec node titles in lane order, so it can never say more than the spec.
import type { StrategyGraph } from "./project";
import type { StrategySpecV1 } from "./spec";

const CIRCLED = ["①", "②", "③", "④", "⑤", "⑥", "⑦", "⑧", "⑨"];

export function toSentence(spec: StrategySpecV1, graph: StrategyGraph): string {
	const live = graph.nodes.filter((n) => n.status !== "off");
	const pick = (lane: string) => live.filter((n) => n.lane === lane);
	const parts: string[] = [];

	const sources = pick("data").filter((n) => n.kind === "source");
	if (sources.length) parts.push(`${sources.map((n) => n.title).join(", ")}에서`);

	const signal = pick("signal");
	const steps = signal.filter((n) => n.kind === "step");
	const others = signal.filter((n) => n.kind !== "step");
	const cond: string[] = others.map((n) => n.title);
	if (steps.length) cond.push(steps.map((n, i) => `${CIRCLED[i] ?? `${i + 1}.`} ${n.title}`).join(" → "));
	if (cond.length) parts.push(`${cond.join(", ")} 순서가 맞으면`);

	const exec = pick("execution");
	if (exec.length) parts.push(`${exec.map((n) => n.title).join(", ")}.`);

	const tail: string[] = [];
	for (const n of [...pick("sizing"), ...pick("risk")]) {
		tail.push(n.status === "unset" && !n.title.includes(":") ? `${n.title}: 미정` : n.title);
	}
	const head = parts.join(" ");
	const sentence = tail.length ? `${head} ${tail.join(" · ")}.` : head;
	return `${spec.title}(${graph.variant}): ${sentence}`;
}

// Style checks for research tips. Quiet on the picked shape, warn on the shape that lost.

export type CopyKind = "verdict" | "chart" | "chip";

export function copyBody(text: string): string {
	const trimmed = text.trim();
	// Source cards start with a location header. Drafts do not: their first paragraph is the tip.
	if (!trimmed.startsWith("위치:")) return trimmed;
	return trimmed.split(/\n\n/).slice(1).join("\n\n").trim();
}

export function sentences(text: string): string[] {
	return text
		.split(/(?<=[.?!。？])\s+/)
		.map((s) => s.trim())
		.filter(Boolean);
}

export function checkCopy(kind: CopyKind, text: string): string[] {
	const body = copyBody(text);
	const first = sentences(body)[0] ?? body;
	const warns: string[] = [];
	if (kind === "verdict") {
		if (/[?？]/.test(first)) {
			warns.push("warn: verdict tip opens with a question — everyday words, decision in the last sentence");
		}
		if (!/(판정|아니다|통과|적용|높았다|통과했다)/.test(body)) {
			warns.push("warn: verdict tip has no decision in the last sentence");
		}
	}
	if (kind === "chart") {
		if (!/[?？]/.test(first)) {
			warns.push("warn: chart tip does not open with a question — one question, then the answer, then the decision");
		}
		if (sentences(body).length > 3) {
			warns.push("warn: chart tip is over three sentences — shorten it");
		}
		if (/\*\*|^\s*[-*] /m.test(body)) {
			warns.push("warn: chart tip uses markdown — a tooltip is a plain paragraph");
		}
	}
	if (kind === "chip" && !/칩/.test(body)) {
		warns.push("warn: chip tip does not name the chip — point at that header chip");
	}
	return warns;
}

if (import.meta.main) {
	const [kind, file] = process.argv.slice(2);
	if (!file || (kind !== "verdict" && kind !== "chart" && kind !== "chip")) {
		console.error("usage: copy-style.ts verdict|chart|chip <file>");
		process.exit(2);
	}
	const text = await Bun.file(file).text();
	for (const line of checkCopy(kind, text)) console.log(line);
}

