/** Round axis ticks inside [min, max], on a 1/2/5 step, always hitting zero when it is in range. */
export function niceTicks(min: number, max: number): number[] {
	if (!Number.isFinite(min) || !Number.isFinite(max)) return [0];
	if (min > max) [min, max] = [max, min];
	if (min === max) return [min === 0 ? 0 : min];
	const rough = (max - min) / 4;
	const pow = 10 ** Math.floor(Math.log10(rough));
	const err = rough / pow;
	const step = (err <= 1.5 ? 1 : err <= 3 ? 2 : err <= 7 ? 5 : 10) * pow;
	const i0 = Math.ceil(min / step - 1e-9);
	const i1 = Math.floor(max / step + 1e-9);
	const ticks: number[] = [];
	for (let i = i0; i <= i1; i++) {
		const v = i * step;
		ticks.push(Math.abs(v) < step * 1e-6 ? 0 : Number(v.toPrecision(12)));
	}
	if (min <= 0 && max >= 0 && !ticks.includes(0)) {
		ticks.push(0);
		ticks.sort((a, b) => a - b);
	}
	return ticks;
}

/** Dotted UTC date. Dashes would make a day 01 look like a January year tick on the line chart. */
export function dateLabel(ms: number): string {
	const d = new Date(ms);
	const p = (n: number) => String(n).padStart(2, "0");
	return `${d.getUTCFullYear()}.${p(d.getUTCMonth() + 1)}.${p(d.getUTCDate())}`;
}

export interface CurveView {
	rule: number[];
	hold: number[];
	ticks: number[];
	labels: string[];
}

function toPercent(values: (number | null)[] | undefined, n: number): number[] {
	let last = 0;
	const out: number[] = [];
	for (let i = 0; i < n; i++) {
		const v = values?.[i];
		if (v != null && Number.isFinite(v)) last = v;
		out.push(last * 100);
	}
	return out;
}

/** Fraction sums → percent. A missing point keeps the previous sum. Null without two points. */
export function curveView(trial: ScreenTrial | null | undefined): CurveView | null {
	const curve = trial?.curve;
	if (!curve || curve.t.length < 2) return null;
	const rule = toPercent(curve.rule, curve.t.length);
	const hold = toPercent(curve.hold, curve.t.length);
	const lo = Math.min(0, ...rule, ...hold);
	const hi = Math.max(0, ...rule, ...hold);
	return { rule, hold, ticks: niceTicks(lo, hi), labels: curve.t.map(dateLabel) };
}

/** The trial at horizon `h`, or the lead trial when the feature was not run there. */
export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h === "lead") return leadTrial(f);
	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
}

export interface ScreenRuleTile {
	id: string;
	group: "entry" | "fill" | "exit";
	name: string;
	label: string;
	tip: string;
}

/**
 * The trade the screen actually scored: the indicator, which side of the reference, the one-way cost,
 * and the hold. A down-regime document adds the gate. A non-tradeable row is marked as reference only.
 */
export function screenRule(doc: ScreenDoc, feature: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const fixed = doc.fixed_sign;
	const sign = fixed ?? trial.train_sign;
	const longSide = sign >= 0;
	const changed = fixed == null && new Set(trial.folds.map((fold) => fold.train_sign)).size > 1;
	const side = longSide ? "롱" : "숏";
	const other = longSide ? "숏" : "롱";
	let label = longSide ? "순방향" : "역추세";
	let tip: string;
	if (fixed != null) {
		const shown = fixed > 0 ? `+${fixed}` : String(fixed);
		tip = `부호를 ${shown}로 고정했다. 기준 위면 ${side}, 아래면 ${other}다.`;
	} else if (changed) {
		label = "부호 바뀜";
		tip = "해마다 학습 부호가 달랐다. 그해 부호대로 기준 위면 롱 또는 숏이다.";
	} else {
		tip = longSide
			? "학습 부호가 양수다. 기준 위면 롱, 아래면 숏이다."
			: "학습 부호가 음수다. 기준 위면 숏, 아래면 롱이다.";
	}
	const bp = (doc.cost_per_side * 1e4).toFixed(0);
	const tiles: ScreenRuleTile[] = [
		{
			id: "indicator",
			group: "entry",
			name: featureName(feature),
			label: feature.tradeable === false ? "참고 지표" : (FAMILY_LABEL[feature.family] ?? "지표"),
			tip: featureDef(feature) || featureName(feature),
		},
		{ id: "direction", group: "entry", name: `기준 위면 ${side}`, label, tip },
	];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			name: "하락장만",
			label: "레짐",
			tip: "종가가 200일 평균 아래인 날만 점수를 매기고 매매한다.",
		});
	}
	tiles.push(
		{
			id: "fill",
			group: "fill",
			name: `편도 ${bp}bp`,
			label: "비용",
			tip: `편도 ${bp}bp(보수적 2배)와 실제 펀딩을 뺀다.`,
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: "청산",
			tip: `${trial.h}${doc.unit} 뒤에 청산한다.`,
		},
	);
	return tiles;
}

