+/** Dotted UTC date. Dashes would make a day 01 look like a January year tick on the line chart. */
+export function dateLabel(ms: number): string {
+	const d = new Date(ms);
+	const p = (n: number) => String(n).padStart(2, "0");
+	return `${d.getUTCFullYear()}.${p(d.getUTCMonth() + 1)}.${p(d.getUTCDate())}`;
+}
+
+export interface CurveView {
+	rule: number[];
+	hold: number[];
+	ticks: number[];
+	labels: string[];
+}
+
+function toPercent(values: (number | null)[] | undefined, n: number): number[] {
+	let last = 0;
+	const out: number[] = [];
+	for (let i = 0; i < n; i++) {
+		const v = values?.[i];
+		if (v != null && Number.isFinite(v)) last = v;
+		out.push(last * 100);
+	}
+	return out;
+}
+
+/** Fraction sums → percent. A missing point keeps the previous sum. Null without two points. */
+export function curveView(trial: ScreenTrial | null | undefined): CurveView | null {
+	const curve = trial?.curve;
+	if (!curve || curve.t.length < 2) return null;
+	const rule = toPercent(curve.rule, curve.t.length);
+	const hold = toPercent(curve.hold, curve.t.length);
+	const lo = Math.min(0, ...rule, ...hold);
+	const hi = Math.max(0, ...rule, ...hold);
+	return { rule, hold, ticks: niceTicks(lo, hi), labels: curve.t.map(dateLabel) };
+}
+
+/** The trial at horizon `h`, or the lead trial when the feature was not run there. */
+export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
+	if (h === "lead") return leadTrial(f);
+	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
+}
